def compute(vars):
    annual_sales_thousand_bpd = vars["v1"] + vars["v2"] + vars["v3"]
    total_million_barrels = annual_sales_thousand_bpd * 365 / 1000
    return {
        "value": total_million_barrels,
        "trace": {
            "annual_sales_thousand_bpd_sum": annual_sales_thousand_bpd,
            "days_per_year": 365,
            "output_meta": {
                "currency": None,
                "scale": "millions",
                "unit": "barrels"
            }
        }
    }
